/* ═══════════════════════════════════════════════════════════════
   3. СОСТОЈБА
   ═══════════════════════════════════════════════════════════════ */
let sostojba;
let brojacTikovi = 0;
let aktivnoJazice = "prodavnica";
let panelValjaSe = true;         // dirty flag за страничниот панел
let posledenTajmer = 0;
let sledenId = 1;

function novaIgra(){
  const pazar = {};
  SORTI.forEach(s => { pazar[s.id] = 1.0; });
  return {
    verzija: KONFIG.VERZIJA,
    parichnik: KONFIG.POCETNI_PARI,
    nivo: 1, iskustvo: 0,
    den: 1, chas: 6,
    brojLei: KONFIG.POCETNI_LEI,
    lei: Array.from({length: KONFIG.MAX_LEI}, () => ({rastenie: null})),
    semki: {skopsko: 1},
    lampa: 0,
    nadgradbi: {navodnuvanje:false, klima:false, sushara:false, rabotnik:false},
    sushara: [],
    magacin: [],
    pazar,
    statistika: {vkupnoBerbi:0, vkupnoGrama:0, vkupnoZaraboteno:0}
  };
}

/* ═══════════════════════════════════════════════════════════════
   4. ПОМОШНИ ФУНКЦИИ
   ═══════════════════════════════════════════════════════════════ */
const stegni = (v, min, max) => Math.min(max, Math.max(min, v));
const najdiSorta  = id => SORTI.find(s => s.id === id);
const najdiNastan = id => NASTANI.find(n => n.id === id);
const tekovnaLampa = () => LAMPI[stegni(sostojba.lampa, 0, LAMPI.length - 1)];
const formatPari = n => Math.round(n).toLocaleString("mk-MK");
const potrebnoIskustvo = nivo => Math.round(500 * Math.pow(nivo, 1.5));

function najdiOcenka(kvalitet){
  return OCENKI.find(o => kvalitet >= o.prag) || OCENKI[OCENKI.length - 1];
}

/** Вкупно игрални часови од семка до зрелост, за дадена сорта. */
function vkupnoChasaDoZrelost(sorta){
  return (KONFIG.CHASA_NIKNENJE + KONFIG.CHASA_VEGETACIJA + KONFIG.CHASA_CVETANJE) * sorta.traenje;
}

function izvesti(poraka, vid){
  const kutija = document.getElementById("izvestuvanja");
  const el = document.createElement("div");
  el.className = "toast" + (vid ? " " + vid : "");
  el.textContent = poraka;
  kutija.appendChild(el);
  setTimeout(() => el.remove(), 3600);
}

function naplati(iznos){
  if (sostojba.parichnik < iznos){ izvesti(TEKST.nemaPari, "greska"); return false; }
  sostojba.parichnik -= iznos;
  return true;
}

function dodadiIskustvo(kolku){
  if (!Number.isFinite(kolku) || kolku <= 0) return;
  sostojba.iskustvo += kolku;
  while (sostojba.iskustvo >= potrebnoIskustvo(sostojba.nivo)){
    sostojba.iskustvo -= potrebnoIskustvo(sostojba.nivo);
    sostojba.nivo++;
    izvesti(TEKST.novoNivo(sostojba.nivo), "pari");
    panelValjaSe = true;
  }
}

/* ═══════════════════════════════════════════════════════════════
   5. ПРЕСМЕТКИ — чисти функции, без странични ефекти
   ═══════════════════════════════════════════════════════════════ */

/** Сува маса во грамови од една берба. */
function presmetajPrinos(sorta, prosekZdravje, lampa){
  const zdrav = stegni(prosekZdravje, 0, 100) / 100;
  return sorta.prinos * Math.pow(zdrav, 1.2) * lampa.prinosMult;
}

/**
 * ╔══════════════════════════════════════════════════════════════╗
 * ║  ОВА Е ГЛАВНОТО КОПЧЕ ЗА БАЛАНС НА ИГРАТА.                   ║
 * ║  Слободно замени го телото — потписот останува ист.          ║
 * ╚══════════════════════════════════════════════════════════════╝
 *
 * Враќа квалитет 0–100, кој потоа станува оценка (Врвен → Слаб)
 * и директно ја множи продажната цена.
 *
 * @param {number} prosekZdravje    0–100, просечно здравје низ целиот живот
 * @param {number} tochnostSushenje 0–1,  1.0 = совршено погоден прозорец за сушење
 * @param {number} genetika         0–1,  вродениот потенцијал на сортата
 * @param {number} lampaBonus       0–14, бонус од ламбата
 * @param {number} deoviSoStetnik   цели денови поминати со нетретиран штетник
 * @returns {number} квалитет 0–100
 *
 * TODO(ти):  Ова е компромис меѓу ДВЕ различни игри и одлуката е твоја:
 *
 *   А) „Наградувај трпение" — дај му голема тежина на `tochnostSushenje`
 *      и остра казна за `deoviSoStetnik`. Играчот што внимава на секое
 *      растение заработува многукратно повеќе од оној што сади масовно.
 *
 *   Б) „Наградувај обем" — дај му поголема тежина на `genetika` и
 *      `lampaBonus`, а помала на грижата. Тогаш вистинската стратегија
 *      е да купуваш подобри семки и повеќе леи, а не да кликаш.
 *
 * Долунаведената имплементација е намерно во средина (грижата носи
 * најмногу, но генетиката поставува таван), за играта да е играбилна
 * веднаш. Замени ја кога ќе решиш во која насока ја сакаш играта.
 */
function presmetajKvalitet(prosekZdravje, tochnostSushenje, genetika, lampaBonus, deoviSoStetnik){
  const zdrav = stegni(prosekZdravje, 0, 100) / 100;
  const suvo  = stegni(tochnostSushenje, 0, 1);
  const gen   = stegni(genetika, 0, 1);

  // Грижата е основата (0–60), сушењето ја модулира.
  const osnova = 60 * Math.pow(zdrav, 1.1) * (0.55 + 0.45 * suvo);
  // Генетиката поставува таван кон кој се стреми резултатот (0–30).
  const taban  = 30 * gen;
  // Опремата е мал, но сигурен додаток.
  const oprema = stegni(lampaBonus, 0, 14);
  // Секој ден со штетник боли трајно.
  const kazna  = Math.max(0, deoviSoStetnik) * 2.5;

  return stegni(osnova + taban + oprema - kazna, 0, 100);
}

/** Претвора поминати денови сушење во точност 0–1 (види §5 од спецификацијата). */
function tochnostOdSushenje(denovi, imaSushara){
  const d1 = imaSushara ? 8 : 9;      // прв идеален ден
  const d2 = imaSushara ? 14 : 12;    // последен идеален ден
  if (denovi <  d1)     return 0.55;  // предвреме
  if (denovi <= d2)     return 1.00;  // идеално
  if (denovi <= d2 + 4) return 0.80;  // прифатливо
  return 0.65;                        // пресушено
}

/** ТХЦ процент, изведен од квалитетот и генетиката. */
function presmetajTHC(kvalitet, genetika){
  return +(8 + 22 * genetika * (stegni(kvalitet, 0, 100) / 100)).toFixed(1);
}

/* ═══════════════════════════════════════════════════════════════
   6. МОТОР — еден тик ја движи целата игра
   ═══════════════════════════════════════════════════════════════ */
function tikni(){
  const prethodenDen = sostojba.den;

  // ── Часовник ──────────────────────────────────────────────
  sostojba.chas += KONFIG.CHASA_PO_TIK;
  while (sostojba.chas >= 24){ sostojba.chas -= 24; sostojba.den++; }
  const novDen = sostojba.den !== prethodenDen;

  const lampa = tekovnaLampa();
  const delDena = KONFIG.CHASA_PO_TIK / 24;   // колку од денот помина овој тик

  // ── Растенија ─────────────────────────────────────────────
  for (let i = 0; i < sostojba.brojLei; i++){
    const r = sostojba.lei[i].rastenie;
    if (!r) continue;
    const sorta = najdiSorta(r.sorta);
    if (!sorta) continue;

    r.vozrast += KONFIG.CHASA_PO_TIK;
    r.brojTikovi++;

    // Потрошувачка на вода и храна
    r.voda    = stegni(r.voda    - KONFIG.VODA_PAD_DEN  * delDena, 0, 100);
    r.hraniva = stegni(r.hraniva - KONFIG.HRANA_PAD_DEN * delDena, 0, 100);

    // Автоматика од надградбите
    if (sostojba.nadgradbi.navodnuvanje && r.voda < KONFIG.AVTO_VODA_PRAG)
      r.voda = KONFIG.AVTO_VODA_PRAG;
    if (sostojba.nadgradbi.rabotnik && r.hraniva < KONFIG.RABOTNIK_PRAG){
      r.hraniva = stegni(r.hraniva + KONFIG.HRANA_DOZA, 0, 100);
      if (r.stetnik === "azot") r.stetnik = null;
    }

    // ── Здравје ───────────────────────────────────────────
    let delta = 0, dobro = true;
    if (r.voda    < KONFIG.VODA_MIN) { delta -= KONFIG.STETA_SUSA;    dobro = false; }
    if (r.voda    > KONFIG.VODA_MAX) { delta -= KONFIG.STETA_DAVENJE; dobro = false; }
    if (r.hraniva < KONFIG.HRANA_MIN){ delta -= KONFIG.STETA_GLAD;    dobro = false; }
    if (r.hraniva > KONFIG.HRANA_MAX){ delta -= KONFIG.STETA_PREGOR;  dobro = false; }

    if (r.stetnik){
      const n = najdiNastan(r.stetnik);
      if (n){ delta -= n.steta; dobro = false; }
      r.deoviSoStetnik += delDena;
    }
    if (dobro) delta += KONFIG.OPORAVUVANJE;

    r.zdravje = stegni(r.zdravje + delta, 0, 100);
    r.zbirZdravje += r.zdravje;

    // ── Фаза ──────────────────────────────────────────────
    const t = sorta.traenje;
    const kNikn = KONFIG.CHASA_NIKNENJE * t;
    const kVeg  = kNikn + KONFIG.CHASA_VEGETACIJA * t;
    const kCvet = kVeg  + KONFIG.CHASA_CVETANJE  * t;

    if      (r.vozrast < kNikn) r.faza = "NIKNENJE";
    else if (r.vozrast < kVeg)  r.faza = "VEGETACIJA";
    else if (r.vozrast < kCvet) r.faza = "CVETANJE";
    else {
      r.faza = "ZRELO";
      const preku = r.vozrast - kCvet - KONFIG.CHASA_ZRELO_PROZOR;
      if (preku > 0){
        // Презревањето трајно го симнува квалитетот преку здравјето
        r.zdravje = stegni(r.zdravje - KONFIG.KAZNA_PREZRELOST_DEN * delDena, 0, 100);
        if (!r.predupredenoPrezrelost){
          r.predupredenoPrezrelost = true;
          izvesti(TEKST.prezrelo, "greska");
        }
      }
    }

    // ── Штетници ──────────────────────────────────────────
    if (!r.stetnik){
      let sansa = KONFIG.SANSA_STETNIK_DEN * delDena;
      if (sostojba.nadgradbi.klima) sansa *= KONFIG.KLIMA_NAMALUVANJE;
      if (Math.random() < sansa){
        const mozni = NASTANI.filter(n => !n.samoCvetanje || r.faza === "CVETANJE");
        r.stetnik = mozni[Math.floor(Math.random() * mozni.length)].id;
        panelValjaSe = true;
      }
    }
  }

  // ── Сушара ────────────────────────────────────────────────
  // Панелот се освежува само кога ќе се смени ЦЕЛ ден, инаку би се
  // прецртувал 4 пати во секунда и постојано би го ресетирал скролот.
  const brzina = sostojba.nadgradbi.sushara ? KONFIG.SUSHARA_ZABRZUVANJE : 1;
  for (const serija of sostojba.sushara){
    const prethoden = Math.floor(serija.denovi);
    serija.denovi += delDena * brzina;
    if (Math.floor(serija.denovi) !== prethoden) panelValjaSe = true;
  }

  // ── Пазар — еднаш дневно ──────────────────────────────────
  if (novDen){
    for (const s of SORTI){
      const drift = 1 + (Math.random() - 0.5) * 2 * KONFIG.PAZAR_DRIFT;
      sostojba.pazar[s.id] = stegni((sostojba.pazar[s.id] || 1) * drift,
                                     KONFIG.PAZAR_MIN, KONFIG.PAZAR_MAX);
    }
    panelValjaSe = true;
  }

  // ── Зачувување ────────────────────────────────────────────
  if (++brojacTikovi % KONFIG.AVTOSEJV_TIKOVI === 0) zachuvaj();
}

/* ═══════════════════════════════════════════════════════════════
   7. АКЦИИ НА ИГРАЧОТ
   ═══════════════════════════════════════════════════════════════ */
function kupiSeme(id){
  const s = najdiSorta(id);
  if (!s) return;
  if (sostojba.nivo < s.nivo){ izvesti(TEKST.potrebnoNivo(s.nivo), "greska"); return; }
  if (!naplati(s.cena)) return;
  sostojba.semki[id] = (sostojba.semki[id] || 0) + 1;
  izvesti(TEKST.kupenoSeme(s.ime));
  panelValjaSe = true;
  iscrtajSe();
}

function otvoriIzborSeme(indeks){
  const dostapni = SORTI.filter(s => (sostojba.semki[s.id] || 0) > 0);
  const telo = document.getElementById("modal-telo");
  document.getElementById("modal-naslov").textContent = `Што садиме во леја ${indeks + 1}?`;

  if (!dostapni.length){
    telo.innerHTML = `<div class="prazno">Немаш семки.<br>Купи од продавницата.</div>`;
  } else {
    telo.innerHTML = dostapni.map(s => `
      <div class="stavka">
        <div class="stavka-glava">
          <span class="stavka-ime">${s.ime}</span>
          <span class="stavka-cena">×${sostojba.semki[s.id]}</span>
        </div>
        <div class="stavka-opis">
          Принос ~${s.prinos} г · Генетика ${Math.round(s.genetika * 100)}%
          · Траење ${s.traenje.toFixed(2)}×
        </div>
        <button onclick="zasadiSemka(${indeks}, '${s.id}')">Засади</button>
      </div>`).join("");
  }
  document.getElementById("modal").classList.add("otvoren");
}

function zatvoriModal(){ document.getElementById("modal").classList.remove("otvoren"); }

function zasadiSemka(indeks, sortaId){
  const s = najdiSorta(sortaId);
  if (!s || (sostojba.semki[sortaId] || 0) <= 0){ izvesti(TEKST.nemaSemki, "greska"); return; }
  if (sostojba.lei[indeks].rastenie) return;

  sostojba.semki[sortaId]--;
  sostojba.lei[indeks].rastenie = {
    sorta: sortaId, faza: "NIKNENJE", vozrast: 0,
    voda: 70, hraniva: 70, zdravje: 100,
    stetnik: null, zbirZdravje: 0, brojTikovi: 0,
    deoviSoStetnik: 0, predupredenoPrezrelost: false
  };
  zatvoriModal();
  izvesti(TEKST.zasadeno(s.ime));
  panelValjaSe = true;
  iscrtajSe();
}

function polej(indeks){
  const r = sostojba.lei[indeks].rastenie; if (!r) return;
  r.voda = stegni(r.voda + KONFIG.VODA_DOZA, 0, 100);
  izvesti(TEKST.polevanje);
  iscrtajSe();
}

function nahrani(indeks){
  const r = sostojba.lei[indeks].rastenie; if (!r) return;
  if (!naplati(KONFIG.CENA_HRANA)) return;
  r.hraniva = stegni(r.hraniva + KONFIG.HRANA_DOZA, 0, 100);
  if (r.stetnik === "azot") r.stetnik = null;   // азотот се лекува со ѓубрење
  izvesti(TEKST.hranenje);
  iscrtajSe();
}

function tretiraj(indeks){
  const r = sostojba.lei[indeks].rastenie; if (!r || !r.stetnik) return;
  const n = najdiNastan(r.stetnik); if (!n){ r.stetnik = null; return; }
  if (!n.tretman){ izvesti(TEKST.samoGubrenje, "greska"); return; }
  if (!naplati(n.cena)) return;
  r.stetnik = null;
  izvesti(TEKST.tretirano(n.tretman));
  iscrtajSe();
}

function oberi(indeks){
  const r = sostojba.lei[indeks].rastenie; if (!r || r.faza !== "ZRELO") return;
  const sorta = najdiSorta(r.sorta); if (!sorta) return;

  const prosekZdravje = r.brojTikovi > 0 ? r.zbirZdravje / r.brojTikovi : 0;
  const suvo   = presmetajPrinos(sorta, prosekZdravje, tekovnaLampa());
  const vlazno = suvo / KONFIG.VLAZNO_VO_SUVO;

  sostojba.sushara.push({
    id: sledenId++, sorta: r.sorta,
    gramaVlazno: vlazno, denovi: 0,
    prosekZdravje, deoviSoStetnik: r.deoviSoStetnik
  });
  sostojba.lei[indeks].rastenie = null;
  sostojba.statistika.vkupnoBerbi++;

  izvesti(TEKST.berba(Math.round(vlazno), sorta.ime), "pari");
  aktivnoJazice = "sushara";
  panelValjaSe = true;
  iscrtajSe();
}

function zavrsiSushenje(serijaId){
  const idx = sostojba.sushara.findIndex(s => s.id === serijaId);
  if (idx === -1) return;
  const serija = sostojba.sushara[idx];
  const sorta = najdiSorta(serija.sorta); if (!sorta) return;

  const tochnost = tochnostOdSushenje(Math.floor(serija.denovi), sostojba.nadgradbi.sushara);
  const kvalitet = presmetajKvalitet(
    serija.prosekZdravje, tochnost, sorta.genetika,
    tekovnaLampa().kvalitetBonus, Math.floor(serija.deoviSoStetnik)
  );
  const ocenka = najdiOcenka(kvalitet);
  const grama  = serija.gramaVlazno * KONFIG.VLAZNO_VO_SUVO;

  sostojba.magacin.push({
    id: sledenId++, sorta: serija.sorta,
    grama, kvalitet, ocenka: ocenka.ime, ocenkaMult: ocenka.mult,
    klasa: ocenka.klasa, thc: null, testirano: false
  });
  sostojba.sushara.splice(idx, 1);
  sostojba.statistika.vkupnoGrama += grama;

  izvesti(TEKST.sushenjeGotovo(Math.round(grama), ocenka.ime), "pari");
  aktivnoJazice = "magacin";
  panelValjaSe = true;
  iscrtajSe();
}

function testirajVoLaboratorija(serijaId){
  const p = sostojba.magacin.find(m => m.id === serijaId);
  if (!p || p.testirano) return;
  const sorta = najdiSorta(p.sorta); if (!sorta) return;
  if (!naplati(KONFIG.CENA_LABORATORIJA)) return;
  p.thc = presmetajTHC(p.kvalitet, sorta.genetika);
  p.testirano = true;
  izvesti(TEKST.analiza(p.thc), "pari");
  panelValjaSe = true;
  iscrtajSe();
}

function cenaNaSerija(p){
  const sorta = najdiSorta(p.sorta); if (!sorta) return 0;
  const pazar = sostojba.pazar[p.sorta] || 1;
  return p.grama * sorta.cenaPoGram * pazar * p.ocenkaMult
         * (p.testirano ? KONFIG.BONUS_LABORATORIJA : 1);
}

function prodaj(serijaId){
  const idx = sostojba.magacin.findIndex(m => m.id === serijaId);
  if (idx === -1) return;
  const p = sostojba.magacin[idx];
  const pari = cenaNaSerija(p);

  sostojba.parichnik += pari;
  sostojba.statistika.vkupnoZaraboteno += pari;
  sostojba.magacin.splice(idx, 1);
  dodadiIskustvo(p.grama * p.ocenkaMult);

  izvesti(TEKST.prodadeno(Math.round(p.grama), pari), "pari");
  panelValjaSe = true;
  iscrtajSe();
}

function cenaNaSlednaLeja(){
  return Math.round(KONFIG.CENA_LEJA_OSNOVA *
    Math.pow(KONFIG.CENA_LEJA_RAST, sostojba.brojLei - KONFIG.POCETNI_LEI));
}

function otkluchiLeja(){
  if (sostojba.brojLei >= KONFIG.MAX_LEI) return;
  if (!naplati(cenaNaSlednaLeja())) return;
  sostojba.brojLei++;
  izvesti(TEKST.novaLeja, "pari");
  panelValjaSe = true;
  iscrtajSe();
}

function kupiLampa(indeks){
  const l = LAMPI[indeks]; if (!l) return;
  if (indeks <= sostojba.lampa) return;
  if (sostojba.nivo < l.nivo){ izvesti(TEKST.potrebnoNivo(l.nivo), "greska"); return; }
  if (!naplati(l.cena)) return;
  sostojba.lampa = indeks;
  izvesti(TEKST.kupenaNadgradba(l.ime), "pari");
  panelValjaSe = true;
  iscrtajSe();
}

function kupiNadgradba(id){
  const n = NADGRADBI.find(x => x.id === id); if (!n) return;
  if (sostojba.nadgradbi[id]) return;
  if (!naplati(n.cena)) return;
  sostojba.nadgradbi[id] = true;
  izvesti(TEKST.kupenaNadgradba(n.ime), "pari");
  panelValjaSe = true;
  iscrtajSe();
}

/* ═══════════════════════════════════════════════════════════════
   8. ПРИКАЗ
   ═══════════════════════════════════════════════════════════════ */
const HUD = {
  pari:  document.getElementById("hud-pari"),
  nivo:  document.getElementById("hud-nivo"),
  den:   document.getElementById("hud-den"),
  lampa: document.getElementById("hud-lampa"),
  grama: document.getElementById("hud-grama"),
  xp:    document.getElementById("hud-xp")
};

const lejaJazli = [];   // трајни DOM јазли, се менуваат на место
// На кој дел од височината на стеблото седи секој пар лисја (одоздола нагоре).
const FRAKCII_LISJA = [0.30, 0.58, 0.84];

/** Растението е чист SVG — растот е само трансформација, без слики. */
function svgRastenie(){
  const list = "M0,0 C-3.2,-11 -3.4,-26 0,-38 C3.4,-26 3.2,-11 0,0 Z";
  const par = (y, skala) => `
    <g class="par-lisja" data-y="${y}" style="transform:translate(50px,${y}px) scale(0)">
      ${[-72,-46,-22,0,22,46,72].map(a =>
        `<path d="${list}" transform="rotate(${a}) scale(${skala})"/>`).join("")}
    </g>`;
  return `<svg viewBox="0 0 100 120" preserveAspectRatio="xMidYMax meet" aria-hidden="true">
    <g class="rastenie-boja" fill="#4ade80">
      <rect class="steblo" x="48.6" y="118" width="2.8" height="0" rx="1.4"/>
      ${par(96, 0.55)}${par(74, 0.72)}${par(52, 0.62)}
      <g class="pupki" opacity="0" fill="#a3e635">
        <ellipse cx="50" cy="38" rx="6.5" ry="11"/>
        <ellipse cx="41" cy="52" rx="4.6" ry="8" opacity=".85"/>
        <ellipse cx="59" cy="52" rx="4.6" ry="8" opacity=".85"/>
      </g>
    </g></svg>`;
}

function izgradiLei(){
  const kutija = document.getElementById("lei");
  kutija.innerHTML = "";
  lejaJazli.length = 0;

  for (let i = 0; i < KONFIG.MAX_LEI; i++){
    const el = document.createElement("div");
    el.className = "leja";
    el.innerHTML = `
      <div class="leja-glava">
        <span class="leja-br">Леја ${i + 1}</span>
        <span class="leja-faza"></span>
      </div>
      <div class="scena">
        ${svgRastenie()}
        <span class="znak-sorta"></span>
        <span class="znak-stetnik"></span>
        <div class="prazna-poraka"></div>
      </div>
      <div class="lenti">
        <div class="lenta"><i>Вода</i><span class="zica"><b class="b-voda"></b></span><u class="u-voda"></u></div>
        <div class="lenta"><i>Храна</i><span class="zica"><b class="b-hrana"></b></span><u class="u-hrana"></u></div>
        <div class="lenta"><i>Здравје</i><span class="zica"><b class="b-zdravje"></b></span><u class="u-zdravje"></u></div>
      </div>
      <div class="akcii"></div>`;
    kutija.appendChild(el);
    lejaJazli.push({
      koren:  el,
      faza:   el.querySelector(".leja-faza"),
      boja:   el.querySelector(".rastenie-boja"),
      steblo: el.querySelector(".steblo"),
      lisja:  el.querySelectorAll(".par-lisja"),
      pupki:  el.querySelector(".pupki"),
      znakSorta:   el.querySelector(".znak-sorta"),
      znakStetnik: el.querySelector(".znak-stetnik"),
      prazna: el.querySelector(".prazna-poraka"),
      bVoda:    el.querySelector(".b-voda"),    uVoda:    el.querySelector(".u-voda"),
      bHrana:   el.querySelector(".b-hrana"),   uHrana:   el.querySelector(".u-hrana"),
      bZdravje: el.querySelector(".b-zdravje"), uZdravje: el.querySelector(".u-zdravje"),
      akcii:  el.querySelector(".akcii")
    });
  }
}

/** Свива растение до нула (за празна или заклучена леја). */
function skrijRastenie(j){
  j.steblo.setAttribute("height", 0);
  j.steblo.setAttribute("y", 118);
  j.pupki.setAttribute("opacity", 0);
  j.pupki.style.transform = "translate(0px,0px)";
  j.lisja.forEach(g => { g.style.transform = `translate(50px,${g.dataset.y}px) scale(0)`; });
}

/** Пишува дугмиња само ако навистина се сменија — инаку :active трепка. */
function postaviAkcii(j, html){
  if (j.akcii.innerHTML !== html) j.akcii.innerHTML = html;
}

function postaviLenta(barEl, textEl, vrednost, boja){
  barEl.style.width = stegni(vrednost, 0, 100).toFixed(0) + "%";
  barEl.style.background = boja;
  textEl.textContent = Math.round(vrednost);
}

function isprazniLenti(j, oznaka){
  ["Voda","Hrana","Zdravje"].forEach(k => {
    j["b" + k].style.width = "0%";
    j["u" + k].textContent = oznaka;
  });
}

function iscrtajLeja(i){
  const j = lejaJazli[i];
  const otklucena = i < sostojba.brojLei;
  const r = sostojba.lei[i].rastenie;

  // Прикажи ги отклучените леи плус ЕДНА следна, како понуда за купување.
  j.koren.style.display = (otklucena || i === sostojba.brojLei) ? "" : "none";

  // ── Заклучена леја ──────────────────────────────────────
  if (!otklucena){
    j.koren.className = "leja zaklucena";
    j.faza.textContent = "";
    j.znakSorta.textContent = "";
    j.znakStetnik.textContent = "";
    j.prazna.textContent = "Заклучена леја";
    j.prazna.style.display = "";
    skrijRastenie(j);

    skrijRastenie(j);
    postaviAkcii(j, sostojba.brojLei < KONFIG.MAX_LEI
      ? `<button class="glavna" onclick="otkluchiLeja()">Отклучи · ${formatPari(cenaNaSlednaLeja())} ден</button>`
      : "");
    isprazniLenti(j, "");
    return;
  }

  // ── Празна леја ─────────────────────────────────────────
  if (!r){
    j.koren.className = "leja";
    j.faza.textContent = "Празна";
    j.znakSorta.textContent = "";
    j.znakStetnik.textContent = "";
    j.prazna.textContent = "Празна леја";
    j.prazna.style.display = "";
    skrijRastenie(j);
    postaviAkcii(j, `<button class="glavna" onclick="otvoriIzborSeme(${i})">Засади</button>`);
    isprazniLenti(j, "—");
    return;
  }

  // ── Засадена леја ───────────────────────────────────────
  const sorta = najdiSorta(r.sorta);
  const zrela = r.faza === "ZRELO";
  const bolna = r.zdravje < 45 || !!r.stetnik;
  j.koren.className = "leja" + (zrela ? " zrela" : "") + (bolna ? " bolna" : "");
  j.faza.textContent = FAZI[r.faza] ? FAZI[r.faza].ime : "—";
  j.prazna.style.display = "none";
  j.znakSorta.textContent = sorta ? sorta.ime : "?";

  if (r.stetnik){
    const n = najdiNastan(r.stetnik);
    j.znakStetnik.textContent = n ? n.kratko : "!";
    j.znakStetnik.title = n ? n.ime : "";
  } else {
    j.znakStetnik.textContent = "";
    j.znakStetnik.title = "";
  }

  // Геометрија на растот
  const traenje = sorta ? sorta.traenje : 1;
  const vkupno = sorta ? vkupnoChasaDoZrelost(sorta) : 1;
  const rast = stegni(r.vozrast / vkupno, 0, 1);
  const zdr  = r.zdravje / 100;

  // Визуелната крива е поблага од вистинскиот раст на времето, за да има
  // што да се гледа и во првите секунди — инаку никулецот е точка на екранот.
  const vid = Math.pow(rast, 0.65);
  const visina = 14 + 70 * vid;
  const vrv = 118 - visina;                    // Y-координата на врвот на стеблото
  j.steblo.setAttribute("height", visina.toFixed(1));
  j.steblo.setAttribute("y", vrv.toFixed(1));

  // Лисјата седат на фиксни ДЕЛОВИ од височината на стеблото, не на фиксни
  // координати — инаку кај младо растение лебдат во воздух над стеблото.
  j.lisja.forEach((g, idx) => {
    const y = 118 - visina * FRAKCII_LISJA[idx];
    const lokalno = stegni((vid - idx * 0.22) / 0.35, 0, 1);
    g.style.transform = `translate(50px,${y.toFixed(1)}px) scale(${lokalno.toFixed(3)})`;
  });

  // Пупките никнуваат на врвот, па и тие се симнуваат заедно со стеблото.
  const pochetokCvet = (KONFIG.CHASA_NIKNENJE + KONFIG.CHASA_VEGETACIJA) * traenje;
  const cvet = (r.faza === "CVETANJE" || zrela)
    ? stegni((r.vozrast - pochetokCvet) / (KONFIG.CHASA_CVETANJE * traenje), 0, 1)
    : 0;
  j.pupki.setAttribute("opacity", cvet.toFixed(2));
  j.pupki.style.transform = `translate(0px,${(vrv - 34).toFixed(1)}px)`;

  // Бојата паѓа од зелена кон кафеава како што паѓа здравјето. Пупките мора
  // да ја следат — инаку мртво растение и понатаму изгледа сочно зелено.
  const nijansa = 25 + 85 * zdr, zasit = 30 + 50 * zdr, svetlo = 22 + 18 * zdr;
  j.boja.setAttribute("fill",
    `hsl(${nijansa.toFixed(0)} ${zasit.toFixed(0)}% ${svetlo.toFixed(0)}%)`);
  j.pupki.setAttribute("fill",
    `hsl(${(nijansa + 12).toFixed(0)} ${(zasit + 15).toFixed(0)}% ${(svetlo + 20).toFixed(0)}%)`);

  // Ленти
  postaviLenta(j.bVoda, j.uVoda, r.voda,
    (r.voda < KONFIG.VODA_MIN || r.voda > KONFIG.VODA_MAX) ? "var(--crvena)" : "var(--sina)");
  postaviLenta(j.bHrana, j.uHrana, r.hraniva,
    (r.hraniva < KONFIG.HRANA_MIN || r.hraniva > KONFIG.HRANA_MAX) ? "var(--crvena)" : "var(--zelena)");
  postaviLenta(j.bZdravje, j.uZdravje, r.zdravje,
    r.zdravje < 45 ? "var(--crvena)" : r.zdravje < 75 ? "var(--zlato)" : "var(--zelena)");

  // Дугмиња
  let html = "";
  if (zrela) html += `<button class="zlatna" onclick="oberi(${i})">Обери</button>`;
  html += `<button onclick="polej(${i})">Полеј</button>`;
  html += `<button onclick="nahrani(${i})">Ѓубри · ${KONFIG.CENA_HRANA}</button>`;
  if (r.stetnik){
    const n = najdiNastan(r.stetnik);
    html += (n && n.tretman)
      ? `<button class="opasna" onclick="tretiraj(${i})">${n.tretman} · ${n.cena} ден</button>`
      : `<button class="opasna" onclick="nahrani(${i})">Ѓубри против азот</button>`;
  }
  postaviAkcii(j, html);
}

function iscrtajSe(){
  HUD.pari.textContent  = formatPari(sostojba.parichnik);
  HUD.nivo.textContent  = sostojba.nivo;
  HUD.den.textContent   = sostojba.den;
  HUD.lampa.textContent = tekovnaLampa().ime;
  HUD.grama.textContent = Math.round(sostojba.statistika.vkupnoGrama) + " г";
  HUD.xp.style.width =
    stegni(sostojba.iskustvo / potrebnoIskustvo(sostojba.nivo) * 100, 0, 100) + "%";

  for (let i = 0; i < KONFIG.MAX_LEI; i++) iscrtajLeja(i);

  if (panelValjaSe){ iscrtajPanel(); panelValjaSe = false; }
}

function iscrtajPanel(){
  const el = document.getElementById("sodrzina");
  document.querySelectorAll(".jazicinja button").forEach(b =>
    b.classList.toggle("aktivno", b.dataset.jaz === aktivnoJazice));

  if      (aktivnoJazice === "prodavnica") el.innerHTML = panelProdavnica();
  else if (aktivnoJazice === "sushara")    el.innerHTML = panelSushara();
  else if (aktivnoJazice === "magacin")    el.innerHTML = panelMagacin();
  else                                     el.innerHTML = panelNadgradbi();
}

function panelProdavnica(){
  return SORTI.map(s => {
    const zakluceno = sostojba.nivo < s.nivo;
    const imam = sostojba.semki[s.id] || 0;
    const pazar = sostojba.pazar[s.id] || 1;
    return `
    <div class="stavka ${zakluceno ? "zakluceno" : ""}">
      <div class="stavka-glava">
        <span class="stavka-ime">${s.ime}</span>
        <span class="stavka-cena">${formatPari(s.cena)} ден</span>
      </div>
      <div class="stavka-opis">
        Принос ~${s.prinos} г · Генетика ${Math.round(s.genetika * 100)}%
        · Траење ${s.traenje.toFixed(2)}×<br>
        Пазар: <b style="color:${pazar >= 1 ? "var(--zelena)" : "var(--crvena)"}">
        ${formatPari(s.cenaPoGram * pazar)} ден/г</b>
        ${imam ? ` · Имаш ${imam} семки` : ""}
      </div>
      <button ${zakluceno ? "disabled" : ""} onclick="kupiSeme('${s.id}')">
        ${zakluceno ? `Потребно ниво ${s.nivo}` : "Купи семе"}
      </button>
    </div>`;
  }).join("");
}

function panelSushara(){
  if (!sostojba.sushara.length)
    return `<div class="prazno">Сушарата е празна.<br>Обери зрело растение за да почнеш.</div>`;

  const imaSushara = sostojba.nadgradbi.sushara;
  const d1 = imaSushara ? 8 : 9;
  const d2 = imaSushara ? 14 : 12;

  return sostojba.sushara.map(s => {
    const sorta = najdiSorta(s.sorta);
    const denovi = Math.floor(s.denovi);
    const napredok = stegni(denovi / d2 * 100, 0, 100);
    const status = denovi <  d1     ? "Прерано — почекај уште"
                 : denovi <= d2     ? "Идеален момент за вадење"
                 : denovi <= d2 + 4 ? "Уште е прифатливо"
                 :                    "Пресушено — квалитетот падна";
    return `
    <div class="stavka">
      <div class="stavka-glava">
        <span class="stavka-ime">${sorta ? sorta.ime : "?"}</span>
        <span class="stavka-cena">${Math.round(s.gramaVlazno)} г мокро</span>
      </div>
      <div class="stavka-opis">
        Ден ${denovi} од сушењето · идеално ${d1}–${d2}<br>${status}
      </div>
      <div class="napredok"><i style="width:${napredok}%"></i></div>
      <button onclick="zavrsiSushenje(${s.id})">Заврши сушење</button>
    </div>`;
  }).join("");
}

function panelMagacin(){
  if (!sostojba.magacin.length)
    return `<div class="prazno">Магацинот е празен.<br>Заврши сушење за да добиеш производ.</div>`;

  return sostojba.magacin.map(p => {
    const sorta = najdiSorta(p.sorta);
    const cena = cenaNaSerija(p);
    const pazar = sostojba.pazar[p.sorta] || 1;
    return `
    <div class="stavka">
      <div class="stavka-glava">
        <span class="stavka-ime">${sorta ? sorta.ime : "?"}</span>
        <span class="oznaka ${p.klasa}">${p.ocenka}</span>
      </div>
      <div class="stavka-opis">
        ${Math.round(p.grama)} г · квалитет ${Math.round(p.kvalitet)}/100
        ${p.testirano ? ` · <b style="color:var(--violet)">${p.thc}% ТХЦ ✓</b>` : ""}<br>
        Пазар ${pazar >= 1 ? "▲" : "▼"} ${(pazar * 100).toFixed(0)}%
        · Вредност <b class="stavka-cena">${formatPari(cena)} ден</b>
      </div>
      <div class="dve">
        <button class="sina" ${p.testirano ? "disabled" : ""}
          onclick="testirajVoLaboratorija(${p.id})">
          ${p.testirano ? "Анализирано ✓" : `Лаб. ${KONFIG.CENA_LABORATORIJA} ден`}
        </button>
        <button onclick="prodaj(${p.id})">Продај</button>
      </div>
    </div>`;
  }).join("");
}

function panelNadgradbi(){
  let html = "";

  if (sostojba.brojLei < KONFIG.MAX_LEI){
    html += `
    <div class="stavka">
      <div class="stavka-glava">
        <span class="stavka-ime">Нова леја</span>
        <span class="stavka-cena">${formatPari(cenaNaSlednaLeja())} ден</span>
      </div>
      <div class="stavka-opis">Имаш ${sostojba.brojLei} од ${KONFIG.MAX_LEI} леи.</div>
      <button onclick="otkluchiLeja()">Отклучи леја</button>
    </div>`;
  }

  html += LAMPI.map((l, i) => {
    if (i === 0) return "";
    const kupena = i <= sostojba.lampa;
    const zakluceno = sostojba.nivo < l.nivo;
    return `
    <div class="stavka ${zakluceno && !kupena ? "zakluceno" : ""}">
      <div class="stavka-glava">
        <span class="stavka-ime">Ламба: ${l.ime}</span>
        <span class="stavka-cena">${kupena ? "✓" : formatPari(l.cena) + " ден"}</span>
      </div>
      <div class="stavka-opis">
        Принос ×${l.prinosMult.toFixed(2)} · Квалитет +${l.kvalitetBonus}
      </div>
      <button ${kupena || zakluceno ? "disabled" : ""} onclick="kupiLampa(${i})">
        ${kupena ? "Инсталирана" : zakluceno ? `Потребно ниво ${l.nivo}` : "Купи"}
      </button>
    </div>`;
  }).join("");

  html += NADGRADBI.map(n => {
    const kupena = !!sostojba.nadgradbi[n.id];
    return `
    <div class="stavka">
      <div class="stavka-glava">
        <span class="stavka-ime">${n.ime}</span>
        <span class="stavka-cena">${kupena ? "✓" : formatPari(n.cena) + " ден"}</span>
      </div>
      <div class="stavka-opis">${n.opis}</div>
      <button ${kupena ? "disabled" : ""} onclick="kupiNadgradba('${n.id}')">
        ${kupena ? "Купено" : "Купи"}
      </button>
    </div>`;
  }).join("");

  return html;
}

/* ═══════════════════════════════════════════════════════════════
   9. ЗАЧУВУВАЊЕ
   ═══════════════════════════════════════════════════════════════ */
function zachuvaj(){
  try{
    localStorage.setItem(KONFIG.KLUC_SEJV, JSON.stringify({s: sostojba, sledenId}));
  }catch(e){
    izvesti(TEKST.sejvGreska, "greska");
  }
}

/** Пополнува полиња што може да недостасуваат во рачно менуван сејв. */
function normalizirajRastenie(r){
  return {
    sorta: r.sorta,
    faza: FAZI[r.faza] ? r.faza : "NIKNENJE",
    vozrast: Number.isFinite(r.vozrast) ? r.vozrast : 0,
    voda:    Number.isFinite(r.voda)    ? stegni(r.voda, 0, 100)    : 70,
    hraniva: Number.isFinite(r.hraniva) ? stegni(r.hraniva, 0, 100) : 70,
    zdravje: Number.isFinite(r.zdravje) ? stegni(r.zdravje, 0, 100) : 100,
    stetnik: najdiNastan(r.stetnik) ? r.stetnik : null,
    zbirZdravje: Number.isFinite(r.zbirZdravje) ? r.zbirZdravje : 0,
    brojTikovi:  Number.isFinite(r.brojTikovi)  ? r.brojTikovi  : 0,
    deoviSoStetnik: Number.isFinite(r.deoviSoStetnik) ? r.deoviSoStetnik : 0,
    predupredenoPrezrelost: !!r.predupredenoPrezrelost
  };
}

function vchitaj(){
  let surovo;
  try{ surovo = localStorage.getItem(KONFIG.KLUC_SEJV); }
  catch(e){ return false; }                 // localStorage целосно недостапен
  if (!surovo) return false;

  let paket;
  try{ paket = JSON.parse(surovo); }
  catch(e){ izvesti(TEKST.vcitajGreska, "greska"); return false; }

  const s = paket && paket.s;
  if (!s || typeof s !== "object"){ izvesti(TEKST.vcitajGreska, "greska"); return false; }
  if (s.verzija !== KONFIG.VERZIJA){ izvesti(TEKST.starVerzija, "greska"); return false; }

  const svez = novaIgra();
  // Прифаќај само познати полиња; сè друго паѓа назад на почетна вредност.
  sostojba = Object.assign(svez, {
    parichnik: Number.isFinite(s.parichnik) ? Math.max(0, s.parichnik) : svez.parichnik,
    nivo:      Number.isFinite(s.nivo) && s.nivo >= 1 ? Math.floor(s.nivo) : 1,
    iskustvo:  Number.isFinite(s.iskustvo) && s.iskustvo >= 0 ? s.iskustvo : 0,
    den:       Number.isFinite(s.den) && s.den >= 1 ? Math.floor(s.den) : 1,
    chas:      Number.isFinite(s.chas) ? stegni(s.chas, 0, 23) : 6,
    brojLei:   stegni(Math.floor(Number(s.brojLei)) || KONFIG.POCETNI_LEI,
                      KONFIG.POCETNI_LEI, KONFIG.MAX_LEI),
    lampa:     stegni(Math.floor(Number(s.lampa)) || 0, 0, LAMPI.length - 1),
    statistika: Object.assign(svez.statistika, s.statistika || {})
  });

  // Леи — отфрли растенија со непозната сорта, дополни им полињата што фалат
  if (Array.isArray(s.lei)){
    for (let i = 0; i < KONFIG.MAX_LEI; i++){
      const r = s.lei[i] && s.lei[i].rastenie;
      sostojba.lei[i].rastenie = (r && najdiSorta(r.sorta)) ? normalizirajRastenie(r) : null;
    }
  }

  // Семки, сушара, магацин, пазар — филтрирај непознати ид-ја и неброеви,
  // за оштетен сејв да не внесе NaN во парите.
  sostojba.semki = {};
  if (s.semki) for (const [id, n] of Object.entries(s.semki))
    if (najdiSorta(id) && Number.isFinite(n) && n > 0) sostojba.semki[id] = Math.floor(n);

  sostojba.sushara = Array.isArray(s.sushara) ? s.sushara.filter(x =>
    x && najdiSorta(x.sorta) && Number.isFinite(x.gramaVlazno) && Number.isFinite(x.denovi)) : [];
  sostojba.magacin = Array.isArray(s.magacin) ? s.magacin.filter(x =>
    x && najdiSorta(x.sorta) && Number.isFinite(x.grama) && Number.isFinite(x.ocenkaMult)) : [];

  for (const sorta of SORTI){
    const v = s.pazar && s.pazar[sorta.id];
    sostojba.pazar[sorta.id] = Number.isFinite(v)
      ? stegni(v, KONFIG.PAZAR_MIN, KONFIG.PAZAR_MAX) : 1;
  }
  for (const n of NADGRADBI)
    sostojba.nadgradbi[n.id] = !!(s.nadgradbi && s.nadgradbi[n.id]);

  // Продолжи ги ид-евата над сè што е вчитано, за да нема судири
  const maxId = Math.max(0,
    ...sostojba.sushara.map(x => Number(x.id) || 0),
    ...sostojba.magacin.map(x => Number(x.id) || 0));
  sledenId = Math.max(Number(paket.sledenId) || 1, maxId + 1);
  return true;
}

/* ═══════════════════════════════════════════════════════════════
   10. СТАРТ
   ═══════════════════════════════════════════════════════════════ */
sostojba = novaIgra();
vchitaj();

document.querySelectorAll(".jazicinja button").forEach(b => {
  b.addEventListener("click", () => {
    aktivnoJazice = b.dataset.jaz;
    panelValjaSe = true;
    iscrtajPanel();
    panelValjaSe = false;
  });
});
document.getElementById("modal").addEventListener("click", e => {
  if (e.target.id === "modal") zatvoriModal();
});
window.addEventListener("beforeunload", zachuvaj);

izgradiLei();
panelValjaSe = true;
iscrtajSe();

/**
 * Часовникот користи delta-time со капа: ако табот бил во заднина и
 * тајмерите биле забавени, наваксуваме најмногу MAX_TIKOVI_NADOMEST тика
 * одеднаш — така враќањето во табот никогаш не прескокнува цела берба.
 * Цртањето е ЕДНАШ по серија тикови, не по секој тик.
 */
posledenTajmer = Date.now();
setInterval(() => {
  const sega = Date.now();
  let dolzni = Math.floor((sega - posledenTajmer) / KONFIG.TIK_MS);
  if (dolzni < 1) return;
  posledenTajmer += dolzni * KONFIG.TIK_MS;
  dolzni = Math.min(dolzni, KONFIG.MAX_TIKOVI_NADOMEST);
  for (let i = 0; i < dolzni; i++) tikni();
  iscrtajSe();
}, KONFIG.TIK_MS);

/* Кука за автоматска проверка (види §11 од спецификацијата). */
window.__test = {
  daj: () => sostojba,
  tikni,
  brzoNapred(n){ for (let i = 0; i < n; i++) tikni(); iscrtajSe(); },
  zasadiSemka, polej, nahrani, tretiraj, oberi,
  zavrsiSushenje, testirajVoLaboratorija, prodaj,
  kupiSeme, kupiLampa, kupiNadgradba, otkluchiLeja,
  presmetajKvalitet, presmetajPrinos, tochnostOdSushenje, presmetajTHC,
  novaIgra, vchitaj, zachuvaj,
  resetiraj(){ sostojba = novaIgra(); sledenId = 1; panelValjaSe = true; iscrtajSe(); }
};
</script>
